_EXPECTED_GUIDANCE_CODES = {
    code for code, _label in LANGUAGE_OPTIONS if code != "en"
}
if not _EXPECTED_GUIDANCE_CODES <= set(_GUIDANCE_ROWS):
    raise ValueError(
        "Help-post guidance catalogs must cover all non-English locales"
    )
if (
    len(HELP_POST_GUIDANCE_KEYS) != 11
    or len(set(HELP_POST_GUIDANCE_KEYS)) != 11
):
    raise ValueError("Help-post guidance keys must contain 11 unique sources")

HELP_POST_GUIDANCE_CATALOGS: dict[str, dict[str, str]] = {
    language: dict(
        zip(
            HELP_POST_GUIDANCE_KEYS,
            _GUIDANCE_ROWS[language].split("|"),
            strict=True,
        )
    )
    for language in _EXPECTED_GUIDANCE_CODES
}
